    CapacityProviderStrategyItem.add_member(:base, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityProviderStrategyItemBase, location_name: 'base', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>The base value designates how many tasks, at a minimum, to run on the specified capacity\n         provider. Only one capacity provider in a capacity provider strategy can have a base\n         defined. If no value is specified, the default value of 0 is used. </p>"}))
