    PipeTargetEcsTaskParameters.add_member(:enable_ecs_managed_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'EnableECSManagedTags', traits: {"smithy.api#default" => false, "smithy.api#documentation" => "<p>Specifies whether to enable Amazon ECS managed tags for the task. For more\n         information, see <a href=\"https://docs.aws.amazon.com/AmazonECS/latest/developerguide/ecs-using-tags.html\">Tagging Your Amazon ECS Resources</a> in the Amazon Elastic Container Service Developer Guide. </p>"}))
