    PipeTargetTimestreamParameters.add_member(:time_field_type, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeFieldType, location_name: 'TimeFieldType', traits: {"smithy.api#documentation" => "<p>The type of time value used.</p>\n         <p>The default is <code>EPOCH</code>.</p>"}))
